    _listeners: Vec<Subscription>,
}
impl EventEmitter<EditEvent> for Editor {}
impl EventEmitter<EditorCompletionEvent> for Editor {}
impl EventEmitter<EditorShortcutEvent> for Editor {}
impl Focusable for Editor {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}
fn from_utf16(s: &str, offset: usize) -> usize {
    let mut units = 0;
    for (i, ch) in s.char_indices() {
        if units + ch.len_utf16() > offset {
            return i;
        }
        units += ch.len_utf16()
    }
    s.len()
}
impl Editor {
    pub fn new(
        label: impl Into<SharedString>,
        mode: InputMode,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        let focus = cx.focus_handle().tab_stop(true);
        let entered = cx.on_focus(&focus, w, |s: &mut Self, _, cx| {
            #[cfg(target_family = "wasm")]
            {
                s.browser_keys = Some(browser_text_input());
            }
            s.cursor = true;
            s.blink = Some(cx.spawn(async move |this, cx| {
                loop {
                    cx.background_executor()
                        .timer(Duration::from_millis(530))
                        .await;
                    if this
                        .update(cx, |s, cx| {
                            s.cursor = !s.cursor;
                            cx.notify()
                        })
                        .is_err()
                    {
                        break;
                    }
                }
            }));
            cx.emit(EditEvent::Focused);
            cx.notify()
        });
        let left = cx.on_blur(&focus, w, |s: &mut Self, _, cx| {
            #[cfg(target_family = "wasm")]
            {
                s.browser_keys = None;
            }
            s.blink = None;
            s.dragging = false;
            s.marked = None;
            cx.emit(EditEvent::Blurred);
            cx.notify()
        });
        Self {
            label: label.into(),
            run_styler: None,
            placeholder: "".into(),
            expanded: None,
            committed_label: None,
            mode,
            value: String::new(),
            anchor: 0,
            caret: 0,
            marked: None,
            ghost: "".into(),
            ghost_chunks: Vec::new(),
            ghost_fade_out: None,
            ghost_preview: false,
            command_submit: false,
            focus,
            revealed: false,
            disabled: false,
            read_only: false,
            font_size: 14.,
            center_text: false,
            description: "".into(),
            layout: None,
            scroll: Default::default(),
            follow_caret: true,
            dragging: false,
            history: vec![],
            redo: vec![],
            cursor: true,
            blink: None,
            #[cfg(target_family = "wasm")]
            browser_keys: None,
            _listeners: vec![entered, left],
        }
    }
    pub fn set_run_styler(&mut self, styler: RunStyler) {
        self.run_styler = Some(styler)
    }
    /// The normalized byte range, including a collapsed caret.
